Q: File upload to wwwroot folder in ASP.NET Core A: <p>Try as follows. File will be uploaded to <code>images</code> folder under <code>wwwroot</code> folder.</p>

<pre><code>private async Task&lt;bool&gt; UploadFile(IFormFile ufile)
{
     if (ufile != null &amp;&amp; ufile.Length &gt; 0)
     {
          var fileName = Path.GetFileName(ufile.FileName);
          var filePath = Path.Combine(Directory.GetCurrentDirectory(), @"wwwroot\images", fileName);
          using (var fileStream = new FileStream(filePath, FileMode.Create))
          {
              await ufile.CopyToAsync(fileStream);
          }
          return true;
      }
      return false;
}
</code></pre>
